DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_T1ZOFGK' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_T1ZOFGK_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_TEXT_1','T1[NEWLINE]Five persistent roles and long-lived upgrade development[NEWLINE]Domination; Culture supported by Headquarters development[NEWLINE][NEWLINE]Train and preserve the original roster, keep useful role combinations close enough to work, and maintain the Gold and technology for genuine upgrades. A successor restores a role after a delay, not the veteran history that was lost.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_TEXT_2','Develop the first locally created Recruits with enough conventional support to survive. Establish Headquarters and a viable economy instead of sending all five valuable roles into an unsupported opening attack.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_TEXT_3','Assign tasks deliberately: Zeus pressures cities, Oner scouts routes, Faker supports contact, Gumayusi finishes wounded enemies and Keria supports legal healing. Keep enough roles in range when the formation matters and save Gold for real unit-type upgrades.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_TEXT_4','Convert accumulated development into a technologically current combined-arms army. Preserve roles and experience through retreats. If a member is lost, defend through the vacancy timer and normally produce an eligible replacement at Headquarters.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_TEXT_5','- Genuine repeated upgrades build persistent development without the small tier cap used by some other veterans.[NEWLINE]- Distinct roles and nearby-roster formations support a coherent core army.[NEWLINE]- Headquarters help train an appropriate supporting force.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_TEXT_6','- A death loses that unit''s XP and upgrade history.[NEWLINE]- Formation strength depends on nearby distinct living roles, not the count of ordinary troops.[NEWLINE]- Successors require a timer and eligible normal production; they do not appear for free.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_TEXT_7','- Focus a valuable role to completion and exploit the resulting formation and replacement gap.[NEWLINE]- Separate the roster or attack where the concentrated core is absent.[NEWLINE]- Pressure upgrade Gold and technology rather than letting the same veterans develop indefinitely.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_TEXT_8','- Counting ordinary troops or duplicate role labels toward Five as One.[NEWLINE]- Expecting purchases or gifts to fill an eligible successor vacancy.[NEWLINE]- Confusing promotions or administrative conversions with genuine unit-type upgrades.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Relentless Seven: A long-lived repeatedly upgraded roster can continue accumulating development beyond Ronaldo''s bounded Reinvention strength tiers.[NEWLINE][NEWLINE]Sol Intellect: An organized early roster can pressure expensive research and Wonder investment before Sol''s mature engine is safe.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Indigo Champion: Losing a developed roster role to a supported team creates a major recovery gap and may also supply an eligible high-value Red reward.[NEWLINE][NEWLINE]The Filthy Realm: A concentrated formation is vulnerable to a well-timed movement and attack shutdown.');
