INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_LEADER_BACKGROUND','Train and preserve the original roster, keep useful role combinations close enough to work, and maintain the Gold and technology for genuine upgrades. A successor restores a role after a delay, not the veteran history that was lost.');
