INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_STRATEGY','Train and preserve the original roster, keep useful role combinations close enough to work, and maintain the Gold and technology for genuine upgrades. A successor restores a role after a delay, not the veteran history that was lost.[NEWLINE][NEWLINE]Develop the first locally created Recruits with enough conventional support to survive. Establish Headquarters and a viable economy instead of sending all five valuable roles into an unsupported opening attack.[NEWLINE][NEWLINE]Assign tasks deliberately: Zeus pressures cities, Oner scouts routes, Faker supports contact, Gumayusi finishes wounded enemies and Keria supports legal healing. Keep enough roles in range when the formation matters and save Gold for real unit-type upgrades.[NEWLINE][NEWLINE]Convert accumulated development into a technologically current combined-arms army. Preserve roles and experience through retreats. If a member is lost, defend through the vacancy timer and normally produce an eligible replacement at Headquarters.');
