INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_LEADER_TEXT_2','Develop the first locally created Recruits with enough conventional support to survive. Establish Headquarters and a viable economy instead of sending all five valuable roles into an unsupported opening attack.[NEWLINE][NEWLINE]Assign tasks deliberately: Zeus pressures cities, Oner scouts routes, Faker supports contact, Gumayusi finishes wounded enemies and Keria supports legal healing. Keep enough roles in range when the formation matters and save Gold for real unit-type upgrades.[NEWLINE][NEWLINE]Convert accumulated development into a technologically current combined-arms army. Preserve roles and experience through retreats. If a member is lost, defend through the vacancy timer and normally produce an eligible replacement at Headquarters.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_T1ZOFGK_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Relentless Seven: A long-lived repeatedly upgraded roster can continue accumulating development beyond Ronaldo''s bounded Reinvention strength tiers.[NEWLINE][NEWLINE]Sol Intellect: An organized early roster can pressure expensive research and Wonder investment before Sol''s mature engine is safe.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Indigo Champion: Losing a developed roster role to a supported team creates a major recovery gap and may also supply an eligible high-value Red reward.[NEWLINE][NEWLINE]The Filthy Realm: A concentrated formation is vulnerable to a well-timed movement and attack shutdown.');
